ISA_EXT_DATA_ENTRY(zicfilp, PRIV_VERSION_1_12_0, ext_zicfilp),
ISA_EXT_DATA_ENTRY(zicfiss, PRIV_VERSION_1_13_0, ext_zicfiss),
/* No smip, smcsps, sscsps, smnip, or ssnip entries */

/* Zicfilp: ELP saved to SPELP on trap entry, cleared afterward */
if (cpu_get_fcfien(env) && riscv_has_ext(env, RVZICFILP)) {
    env->mstatus = set_field(env->mstatus, MSTATUS_SPELP, get_field(env->mstatus, MSTATUS_MPV));
}
/* No Smip: no x10-x15 save, no SP↔XSP swap, no MIPU/SIPU check */

if (cpu_get_fcfien(env)) {
    env->elp = get_field(env->mstatus, MSTATUS_SPELP);
    env->mstatus = set_field(env->mstatus, MSTATUS_SPELP, 0);
}
/* No Smip: no sipopret decode, no x10-x15 restore, no scspspop */

if (cpu_get_fcfien(env)) {
    env->elp = get_field(env->mstatus, MSTATUS_MPELP);
    env->mstatus = set_field(env->mstatus, MSTATUS_MPELP, 0);
}
/* No Smip: no mipopret decode, no x10-x15 restore, no mcspspop */

/* Existing Zicfiss decode (not Smip): */
sspush      ......  .....   ..... 010 ..... 1111011 @sfence_vm
sspopchk    ......  .....   ..... 100 ..... 1111011 @sfence_vm
/* No mipopret, sipopret, mcspspush/mcspspop, scspspush/scspspop decode */

/* Existing CFI registers: */
#define CSR_SSP 0x011
/* No MSPCS (0x349), SSPCS (0x149), MPISTATUS (0x346), SPISTATUS (0x146) */

BOOL_FIELD(ext_zicfilp)
BOOL_FIELD(ext_zicfiss)
/* No ext_smip, ext_smcsps, ext_sscsps fields */

VMSTATE_BOOL(env.elp, RISCVCPU),
VMSTATE_UINTTL(env.ssp, RISCVCPU),
/* No xsp, mpistatus, spistatus, mspcs, sspcs VMState entries */

env->elp = false;
env->ssp = 0;
/* No Smip reset: no xsp, mspcs, sspcs, mpistatus, spistatus init */
